import java.lang.reflect.Array;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static <T> void copy(List<? super T> dest, List<? extends T> src) {
        for (T item : src) dest.add(item);
    }

    @SuppressWarnings("unchecked")
    static <T> T[] newArray(Class<T> type, int size) {
        return (T[]) Array.newInstance(type, size);
    }

    abstract static class TypeRef<T> {
        final Type type;
        TypeRef() {
            Type superType = getClass().getGenericSuperclass();
            this.type = ((ParameterizedType) superType).getActualTypeArguments()[0];
        }
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    static void pollute(List<String> strings) {
        List raw = strings;
        raw.add(123);
    }

    public static void main(String[] args) {
        List<String> strings = new ArrayList<>();
        List<Integer> integers = new ArrayList<>();
        System.out.println("same runtime class: " + (strings.getClass() == integers.getClass()));
        assert strings.getClass() == integers.getClass();

        List<Number> numbers = new ArrayList<>();
        copy(numbers, List.of(1, 2, 3));
        System.out.println("copied numbers: " + numbers);
        assert numbers.equals(List.of(1, 2, 3));

        Integer[] arr = newArray(Integer.class, 2);
        arr[0] = 42;
        System.out.println("runtime array type: " + arr.getClass().getTypeName());
        assert arr.getClass().getTypeName().equals("java.lang.Integer[]");

        Type captured = new TypeRef<List<String>>() {}.type;
        System.out.println("captured type: " + captured.getTypeName());
        assert captured.getTypeName().contains("java.util.List<java.lang.String>");

        boolean classCast = false;
        try {
            pollute(strings);
            String first = strings.get(0);
            System.out.println(first);
        } catch (ClassCastException e) {
            classCast = true;
            System.out.println("heap pollution triggered: " + e.getClass().getSimpleName());
        }
        assert classCast;
    }
}
